def execution_waves(steps):
    records = list(steps)
    order = [record["id"] for record in records]
    if any(type(step_id) is not str or not step_id for step_id in order) or len(order) != len(set(order)):
        raise ValueError("invalid step id")
    needs = {record["id"]: tuple(record["needs"]) for record in records}
    if any(dependency not in needs for values in needs.values() for dependency in values):
        raise ValueError("unknown dependency")
    completed = set()
    result = []
    while len(completed) != len(order):
        ready = [step_id for step_id in order if step_id not in completed and all(dependency in completed for dependency in needs[step_id])]
        if not ready:
            raise ValueError("dependency cycle")
        result.append(ready)
        completed.update(ready)
    return result

def execution_waves(steps):
    items = list(steps)
    remaining = {item["id"] for item in items}
    result = []
    while remaining:
        ready = [item["id"] for item in items if item["id"] in remaining and not (set(item["needs"]) & remaining)]
        if not ready:
            raise ValueError("invalid dependencies")
        result.append(ready[:1])
        remaining.remove(ready[0])
    return result

def execution_waves(steps):
    items = list(steps)
    remaining = {item["id"] for item in items}
    result = []
    while remaining:
        ready = [item["id"] for item in items if item["id"] in remaining and not ({need for need in item["needs"] if need in remaining})]
        if not ready:
            raise ValueError("cycle")
        result.append(ready)
        remaining.difference_update(ready)
    return result

def period_summary(opening, entries, start, end):
    if start > end:
        raise ValueError("start after end")
    before = _money(opening)
    credits = _money(0)
    debits = _money(0)
    for entry in entries:
        amount = _money(entry["amount"])
        signed = amount if entry["kind"] == "credit" else -amount
        if entry["date"] < start:
            before += signed
        elif entry["date"] <= end:
            if entry["kind"] == "credit":
                credits += amount
            else:
                debits += amount
    return {"opening": format(before, ".2f"), "credits": format(credits, ".2f"), "debits": format(debits, ".2f"), "closing": format(before + credits - debits, ".2f")}

def period_summary(opening, entries, start, end):
    if start > end:
        raise ValueError("invalid period")
    opening_value, credit_total, debit_total = _money(opening), Decimal(0), Decimal(0)
    for row in entries:
        value = _money(row["amount"])
        if row["date"] < start:
            opening_value += value if row["kind"] == "credit" else -value
        if start <= row["date"] <= end:
            if row["kind"] == "credit":
                credit_total += value
            else:
                debit_total += value
    values = (opening_value, credit_total, debit_total, opening_value + credit_total - debit_total)
    return dict(zip(("opening", "credits", "debits", "closing"), (format(value, ".2f") for value in values)))

