def due_notification_ids(records, now):
    import datetime
    def instant(value):
        if value.endswith("Z"):
            value = value[:-1] + "+00:00"
        return datetime.datetime.fromisoformat(value).timestamp()
    cutoff = instant(now)
    return [item["id"] for item in records if instant(item["scheduled_at"]) <= cutoff]

def due_notification_ids(records, now):
    def wall(value):
        return value[:19]
    return [record["id"] for record in records if wall(record["scheduled_at"]) <= wall(now)]

def running_balances(opening, entries):
    balance, result, seen = _money(opening), [], set()
    for entry in entries:
        entry_id = entry.get("id")
        kind = entry["kind"]
        if kind not in {"credit", "debit"}:
            raise ValueError("unsupported entry kind")
        apply = not isinstance(entry_id, str) or not entry_id or entry_id not in seen
        if isinstance(entry_id, str) and entry_id:
            seen.add(entry_id)
        if apply:
            amount = _money(entry["amount"])
            balance += amount if kind == "credit" else -amount
        result.append(format(balance, ".2f"))
    return result

