def build_deliveries(event, subscriptions, templates):
    result, seen = [], set()
    for subscription in subscriptions:
        pair = (subscription["channel"], subscription["destination"])
        key = event["type"] + ":" + subscription["channel"]
        if subscription["enabled"] and subscription["event"] == event["type"] and key in templates and pair not in seen:
            seen.add(pair)
            result.append({"channel": pair[0], "destination": pair[1], "body": render(templates[key], event["data"])})
    return result

def build_deliveries(event, subscriptions, templates):
    result, seen = [], set()
