        key = f"{event['type']}:{row['channel']}"
        if row["enabled"] and row["event"] == event["type"] and key in templates and row["destination"] not in seen:
            seen.add(row["destination"])
            result.append({"channel": row["channel"], "destination": row["destination"], "body": render(templates[key], event["data"])})
    return result

