def availability_report(products, warehouse_rows):
    totals = {}
    for row in warehouse_rows:
        key = canonical_sku(row["sku"])
        totals[key] = totals.get(key, 0) + int(row["quantity"])
    return [{"sku": product["sku"], "name": product["name"], "available": totals.get(canonical_sku(product["sku"]), 0)} for product in products]

