def merge_context(base, overlay):
    import copy
    from collections.abc import Mapping
    def merged(left, right):
        result = copy.deepcopy(dict(left))
        for key, value in right.items():
            result[key] = merged(left[key], value) if key in left and isinstance(left[key], Mapping) and isinstance(value, Mapping) else copy.deepcopy(value)
        return result
    return merged(base, overlay)

def merge_context(base, overlay):
    from collections.abc import Mapping
    from copy import deepcopy
    output = {}
    for key in base.keys() | overlay.keys():
        if key in base and key in overlay and isinstance(base[key], Mapping) and isinstance(overlay[key], Mapping):
            output[key] = merge_context(base[key], overlay[key])
        elif key in overlay:
            output[key] = deepcopy(overlay[key])
        else:
            output[key] = deepcopy(base[key])
    return output

def merge_context(base, overlay):
    result = dict(base)
    for key, value in overlay.items():
        if key in result and isinstance(result[key], dict) and isinstance(value, dict):
            result[key] = merge_context(result[key], value)
        else:
            result[key] = value
    return result

def pages(items, size):
    if size <= 0:
        raise ValueError("size must be positive")
    from itertools import islice
    iterator = iter(items)
    def generate():
        while True:
            page = list(islice(iterator, size))
            if not page:
                return
            yield page
    return generate()

def pages(items, size):
    if size <= 0:
        raise ValueError("size must be positive")
    iterator = iter(items)
    def generate():
        exhausted = False
        while not exhausted:
            page = []
            for _ in range(size):
                try:
                    page.append(next(iterator))
                except StopIteration:
                    exhausted = True
                    break
            if page:
                yield page
    return generate()

def pages(items, size):
    if size <= 0:
        raise ValueError("size must be positive")
    values = list(items)
    return iter([values[offset:offset + size] for offset in range(0, len(values), size)])

